import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.DaAAbehN.js";const p=JSON.parse('{"title":"Lesson 6: Understanding the Codex Interface","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-2/lesson-6.md","filePath":"en/modules/module-2/lesson-6.md"}'),i={name:"en/modules/module-2/lesson-6.md"};function n(s,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="lesson-6-understanding-the-codex-interface" tabindex="-1">Lesson 6: Understanding the Codex Interface <a class="header-anchor" href="#lesson-6-understanding-the-codex-interface" aria-label="Permalink to &quot;Lesson 6: Understanding the Codex Interface&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Become familiar with the Codex desktop app&#39;s layout, core features, and operation logic ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Interface tour + concept explanation</p></blockquote><hr><h2 id="i-interface-overview" tabindex="-1">I. Interface Overview <a class="header-anchor" href="#i-interface-overview" aria-label="Permalink to &quot;I. Interface Overview&quot;">​</a></h2><p>After opening the Codex desktop app, you&#39;ll see the following main areas:</p><h3 id="left-panel" tabindex="-1">Left Panel <a class="header-anchor" href="#left-panel" aria-label="Permalink to &quot;Left Panel&quot;">​</a></h3><ul><li><strong>Conversation Manager</strong>: Shows the list of historical conversations. You can quickly switch between them or start a new one.</li><li><strong>Workspace</strong>: Displays the file structure of the current project/folder.</li><li><strong>Plugins / Skills</strong>: Shows available built-in skills and extensions.</li></ul><h3 id="center-chat-dialog" tabindex="-1">Center: Chat Dialog <a class="header-anchor" href="#center-chat-dialog" aria-label="Permalink to &quot;Center: Chat Dialog&quot;">​</a></h3><ul><li>This is the main area where you converse with Codex.</li><li>You can enter text commands, upload files, and view Codex&#39;s responses and execution results.</li></ul><h3 id="right-bottom-panel-varies-by-version" tabindex="-1">Right / Bottom Panel (varies by version) <a class="header-anchor" href="#right-bottom-panel-varies-by-version" aria-label="Permalink to &quot;Right / Bottom Panel (varies by version)&quot;">​</a></h3><ul><li>File preview area</li><li>Code editor</li><li>Execution logs</li></ul><hr><h2 id="ii-core-concept-workspace" tabindex="-1">II. Core Concept: Workspace <a class="header-anchor" href="#ii-core-concept-workspace" aria-label="Permalink to &quot;II. Core Concept: Workspace&quot;">​</a></h2><p><strong>The workspace is one of Codex&#39;s most important concepts.</strong></p><p>When you set a folder as your workspace, you&#39;re essentially telling Codex: &quot;You can read, create, and modify files within this folder.&quot;</p><h3 id="why-do-you-need-a-workspace" tabindex="-1">Why do you need a workspace? <a class="header-anchor" href="#why-do-you-need-a-workspace" aria-label="Permalink to &quot;Why do you need a workspace?&quot;">​</a></h3><ol><li><strong>Safety boundary</strong>: Codex can only operate within the specified workspace, without affecting other files.</li><li><strong>Context focus</strong>: Codex can read all files in the workspace and understand your project structure.</li><li><strong>Controllable results</strong>: All modifications happen within the workspace, making them easy to track and manage.</li></ol><h3 id="how-to-set-a-workspace" tabindex="-1">How to set a workspace? <a class="header-anchor" href="#how-to-set-a-workspace" aria-label="Permalink to &quot;How to set a workspace?&quot;">​</a></h3><ol><li>Find the &quot;Open Folder&quot; or &quot;Select Workspace&quot; button in the Codex interface.</li><li>Browse to your target folder and confirm.</li><li>The left panel will display the file tree of that folder.</li></ol><hr><h2 id="iii-permission-modes" tabindex="-1">III. Permission Modes <a class="header-anchor" href="#iii-permission-modes" aria-label="Permalink to &quot;III. Permission Modes&quot;">​</a></h2><p>Codex offers three permission modes to control the AI&#39;s file operation scope:</p><h3 id="_1-default-permission-recommended-for-beginners" tabindex="-1">1. Default Permission (Recommended for Beginners) <a class="header-anchor" href="#_1-default-permission-recommended-for-beginners" aria-label="Permalink to &quot;1. Default Permission (Recommended for Beginners)&quot;">​</a></h3><p>Codex asks for your approval before executing any file modifications.</p><ul><li>Safest option, suitable for new users</li><li>You can evaluate each operation before allowing it.</li></ul><h3 id="_2-auto-review-recommended-for-advanced-users" tabindex="-1">2. Auto-Review (Recommended for Advanced Users) <a class="header-anchor" href="#_2-auto-review-recommended-for-advanced-users" aria-label="Permalink to &quot;2. Auto-Review (Recommended for Advanced Users)&quot;">​</a></h3><p>Codex can execute operations automatically, and you can review and audit afterward.</p><ul><li>More efficient, suitable when you trust Codex&#39;s working style</li><li>⚠️ It&#39;s recommended to back up important files before operations.</li></ul><h3 id="_3-full-access-not-recommended" tabindex="-1">3. Full Access (Not Recommended) <a class="header-anchor" href="#_3-full-access-not-recommended" aria-label="Permalink to &quot;3. Full Access (Not Recommended)&quot;">​</a></h3><p>Codex has full read/write permission to files in your workspace.</p><ul><li>Highest risk, not recommended for beginners</li><li>Only enable this if you fully understand the risks.</li></ul><blockquote><p>⚠️ <strong>Security reminder</strong>: Regardless of which permission mode you choose, never enter passwords, bank card numbers, or other sensitive information into Codex.</p></blockquote><hr><h2 id="iv-in-lesson-practice-tasks" tabindex="-1">IV. In-Lesson Practice Tasks <a class="header-anchor" href="#iv-in-lesson-practice-tasks" aria-label="Permalink to &quot;IV. In-Lesson Practice Tasks&quot;">​</a></h2><ol><li>Open the Codex desktop app</li><li>Create a test folder (e.g., &quot;Codex Practice&quot; on your desktop)</li><li>Set that folder as Codex&#39;s workspace</li><li>Observe the file tree changes in the left panel</li><li>Try switching the permission mode from &quot;Default&quot; to &quot;Auto-Review&quot; (just for experience, you can switch it back anytime).</li></ol><hr><h2 id="v-summary" tabindex="-1">V. Summary <a class="header-anchor" href="#v-summary" aria-label="Permalink to &quot;V. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Knowledge Point</th><th>Core Content</th></tr></thead><tbody><tr><td>Workspace</td><td>Codex&#39;s File Operations scope, like a &quot;sandbox&quot;</td></tr><tr><td>Left panel</td><td>Conversation manager + workspace file tree + skills list</td></tr><tr><td>Chat dialog</td><td>Main area for entering commands and viewing results</td></tr><tr><td>Permission modes</td><td>Default (safe), Auto-Review (efficient), Full Access (high risk)</td></tr></tbody></table><hr><h2 id="vi-next-step" tabindex="-1">VI. Next Step <a class="header-anchor" href="#vi-next-step" aria-label="Permalink to &quot;VI. Next Step&quot;">​</a></h2><p><a href="./lesson-7.html">→ Lesson 7: Your First Conversation</a></p>',41)])])}const m=o(i,[["render",n]]);export{p as __pageData,m as default};
